// This file is generated by AI.

// 配音工作台: 服务与启动配置、任务队列、角色库。
//
// 布局 (参考 WebGAL Terre 图形编辑器的语句面板: 分组紧凑、字段按内容宽度排布):
// ┌ 页头 ──────────────────────────────────────────────┐
// │ 配音工作台 · 服务状态            [启动服务] [帮助]   │
// ├ 左栏 (服务配置 / 默认设置) ─┬ 右栏 (任务队列 / 日志) ┤
// │ 整合包 / 启动方式 / 解释器… │ 队列与日志 (独立滚动)   │
// ├─────────────────────────────┴───────────────────────┤
// │ 角色库 (占满剩余高度, 内部滚动)                       │
// └─────────────────────────────────────────────────────┘
//
// 两栏内的分组都做成**分页**, 而不是把所有字段堆成一长条: 字段一多就必须滚动,
// 而滚动会把"启动服务"这类关键操作推到视野之外。

import { Button, Field, Input, ProgressBar, Spinner } from '@fluentui/react-components';
import {
  ArrowClockwiseRegular,
  ArrowDownloadRegular,
  DismissRegular,
  ErrorCircleRegular,
  FolderRegular,
  PlayRegular,
  QuestionCircleRegular,
  RecordStopRegular,
  WrenchRegular,
} from '@fluentui/react-icons';
import { open as openDialog, save as saveDialog } from '@tauri-apps/plugin-dialog';
import { revealItemInDir } from '@tauri-apps/plugin-opener';
import { useEffect, useState } from 'react';

import type { CondaEnv, LaunchConfig, LaunchMode } from '../commands/voice';
import { Select, toOptions } from '../components/Select';
import { fs } from '../lib/fs';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { formatEta } from './estimate';
import { errorSummary } from './errorText';
import { RoleListPanel } from './RoleListPanel';
import { LANGUAGE_LABELS, type VoiceTask } from './types';
import { VoiceCacheDialog } from './VoiceCacheDialog';
import { VoiceErrorDialog } from './VoiceErrorDialog';

type ConfigPage = 'service' | 'defaults';
type QueuePage = 'queue' | 'log';

export function VoiceWorkbench() {
  // 帮助是独立选项卡, 直接由工作台发起打开
  const onOpenHelp = () => useAppStore.getState().openVoiceGuide();
  const status = useAppStore((state) => state.voiceStatus);
  const logs = useAppStore((state) => state.voiceLogs);
  useAppStore((state) => state.voiceTick);

  const settings = voiceController.getSettings();
  const [rootPath, setRootPath] = useState(settings.launch?.root ?? '');
  const [launch, setLaunch] = useState<LaunchConfig | null>(settings.launch);
  const [condaEnvs, setCondaEnvs] = useState<CondaEnv[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [configPage, setConfigPage] = useState<ConfigPage>('service');
  const [queuePage, setQueuePage] = useState<QueuePage>('queue');
  const [changeDialogOpen, setChangeDialogOpen] = useState(false);
  /** 正在查看失败详情的任务 (null 表示不显示弹窗) */
  const [errorTask, setErrorTask] = useState<VoiceTask | null>(null);

  const defaults = settings.defaults;
  const summary = voiceController.queueSummary();
  const running = status === 'ready' || status === 'starting';

  useEffect(() => {
    if (settings.launch) {
      setRootPath(settings.launch.root);
      setLaunch(settings.launch);
    }
    // conda 环境列表在打开工作台时扫描一次 (扫描失败的常见原因是本机没有 conda)
    void voiceController.listCondaEnvs().then(setCondaEnvs);
  }, []);

  /** 更新并持久化启动配置 */
  const patchLaunch = (patch: Partial<LaunchConfig>) => {
    if (!launch) return;
    const next = { ...launch, ...patch };
    setLaunch(next);
    voiceController.updateSettings({ launch: next });
  };

  /** 选择整合包目录并探测 */
  const pickRoot = async () => {
    const selected = await openDialog({ directory: true, multiple: false, title: '选择 GPT-SoVITS 整合包目录' });
    if (typeof selected !== 'string') return;
    setRootPath(selected);
    setBusy(true);
    setError(null);
    try {
      const config = await voiceController.detect(selected);
      setLaunch(config);
      voiceController.updateSettings({ launch: config });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  /**
   * 整合包目录按钮 (目录的唯一入口)。
   *
   * 尚未选择时点击进入选择; 已选择时点击在文件管理器中打开 —— 因此不需要额外的
   * 「选择…」按钮, 也就不会出现两个长得一样、含义却不同的文件夹图标。
   */
  const onRootAction = () => {
    if (rootPath) void revealItemInDir(rootPath);
    else void pickRoot();
  };

  /** 选择 Python 解释器文件 (仅「外部 Python」用) */
  const pickProgram = async () => {
    if (!launch) return;
    const picked = await openDialog({
      multiple: false,
      title: '选择 Python 解释器',
      filters: [{ name: '可执行文件', extensions: ['exe'] }],
    });
    if (typeof picked !== 'string') return;
    patchLaunch({ mode: { kind: 'python', program: picked } });
  };

  const start = async () => {
    if (!launch) {
      setError('请先选择 GPT-SoVITS 整合包目录');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await voiceController.startGsv(launch);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  /*
   * 停止服务**不禁用**: 启动过程中最需要的能力就是"取消" —— 首次加载模型要几十秒,
   * 路径填错时要能立刻停下, 而不是干等它自己失败。
   */
  const stop = async () => {
    setBusy(true);
    try {
      await voiceController.stopGsv();
    } finally {
      setBusy(false);
    }
  };

  const statusLabel =
    status === 'ready' ? '就绪' : status === 'starting' ? '启动中…' : status === 'error' ? '错误' : '未启动';

  return (
    <div className="voice-workbench">
      {/* -------- 页头: 标题 + 主要操作 -------- */}
      <div className="voice-workbench-header">
        <div className="voice-workbench-heading">
          <h1>配音工作台</h1>
          <p>
            GPT-SoVITS 服务、角色库与任务队列
            <span className={`workbench-status workbench-status-${status}`}> · {statusLabel}</span>
          </p>
        </div>
        <div className="voice-workbench-actions">
          {running ? (
            <Button
              appearance="secondary"
              className="danger-outline"
              icon={<RecordStopRegular />}
              onClick={() => void stop()}
            >
              停止服务
            </Button>
          ) : (
            <Button appearance="primary" icon={<PlayRegular />} disabled={busy} onClick={() => void start()}>
              启动服务
            </Button>
          )}
          <Button appearance="secondary" icon={<QuestionCircleRegular />} onClick={onOpenHelp}>
            帮助
          </Button>
        </div>
      </div>

      {/* -------- 左: 服务配置 / 右: 运行状态 -------- */}
      <div className="voice-workbench-columns">
        <section className="workbench-card workbench-config">
          <div className="workbench-card-head">
            <h2 className="workbench-card-title">服务配置</h2>
            <div className="workbench-tabs">
              <button className={configPage === 'service' ? 'active' : ''} onClick={() => setConfigPage('service')}>
                启动方式
              </button>
              <button className={configPage === 'defaults' ? 'active' : ''} onClick={() => setConfigPage('defaults')}>
                合成设置
              </button>
            </div>
          </div>

          {configPage === 'service' ? (
            <>
              <Field label="GPT-SoVITS 整合包目录">
                <div className="workbench-input-row">
                  <Input value={rootPath} readOnly placeholder="选择包含 api_v2.py 的整合包目录" />
                  <Button
                    appearance="secondary"
                    icon={<FolderRegular />}
                    title={rootPath ? '在文件管理器中打开' : '选择整合包目录'}
                    disabled={busy && !rootPath}
                    onClick={onRootAction}
                  />
                </div>
              </Field>

              {launch && (
                <div className="workbench-grid">
                  <Field label="启动方式">
                    <Select
                      value={launch.mode.kind}
                      title={modeLabel(launch)}
                      options={[
                        { value: 'embedded', label: '整合包内置运行时' },
                        { value: 'python', label: '自定义 Python 解释器' },
                        { value: 'conda', label: 'conda 运行环境' },
                        { value: 'command', label: '自定义命令' },
                      ]}
                      onChange={(kind) => patchLaunch({ mode: defaultMode(kind, launch) })}
                    />
                  </Field>

                  {/*
                    按启动方式给出不同的第二项:
                    * 内置运行时 -> 只读显示解释器路径 (由整合包决定, 不可改);
                    * conda      -> 环境下拉 (从本机扫描), 没有文件夹图标;
                    * 外部 Python -> 解释器路径 + 文件夹图标;
                    * 自定义命令 -> 一整条命令 + 参数, 没有文件夹图标。
                  */}
                  {launch.mode.kind === 'embedded' && (
                    <Field label="Python 解释器">
                      <Input value={launch.mode.program} readOnly title="由整合包内置运行时决定" />
                    </Field>
                  )}

                  {launch.mode.kind === 'conda' && (
                    <Field label="conda 运行环境">
                      <Select
                        value={launch.mode.env}
                        title="选择本机已安装的 conda 环境（通过 conda run 调用，与手动激活等价）"
                        placeholder={condaEnvs.length === 0 ? '未发现 conda 环境' : '选择环境'}
                        options={condaEnvs.map((env) => ({ value: env.name, label: env.displayName }))}
                        onChange={(env) => patchLaunch({ mode: { kind: 'conda', env, program: null } })}
                      />
                    </Field>
                  )}

                  {launch.mode.kind === 'python' && (
                    <Field label="Python 解释器">
                      <div className="workbench-input-row">
                        <Input
                          value={launch.mode.program}
                          onChange={(_, data) => patchLaunch({ mode: { kind: 'python', program: data.value } })}
                        />
                        <Button
                          appearance="secondary"
                          icon={<FolderRegular />}
                          title="选择 Python 解释器"
                          onClick={() => void pickProgram()}
                        />
                      </div>
                    </Field>
                  )}

                  {launch.mode.kind === 'command' && (
                    <Field label="命令" className="workbench-field-wide">
                      <Input
                        value={launch.mode.command}
                        placeholder="在这里直接写完整命令"
                        onChange={(_, data) => patchLaunch({ mode: { kind: 'command', command: data.value } })}
                      />
                    </Field>
                  )}

                  {launch.mode.kind !== 'command' && (
                    <>
                      <Field label="控制脚本">
                        <Input value={launch.script} onChange={(_, data) => patchLaunch({ script: data.value })} />
                      </Field>

                      <Field label="推理配置">
                        <Input
                          value={launch.inferConfig}
                          onChange={(_, data) => patchLaunch({ inferConfig: data.value })}
                        />
                      </Field>
                    </>
                  )}
                </div>
              )}
            </>
          ) : (
            <div className="workbench-grid">
              <Field label="默认语言">
                <Select
                  value={defaults.language}
                  title="新对话默认使用的语言"
                  options={toOptions(LANGUAGE_LABELS)}
                  onChange={(language) => voiceController.updateSettings({ defaults: { ...defaults, language } })}
                />
              </Field>
            </div>
          )}

          {error && (
            <p className="voice-error">
              <ErrorCircleRegular /> {error}
            </p>
          )}
        </section>

        <section className="workbench-card workbench-queue">
          <div className="workbench-card-head">
            <h2 className="workbench-card-title">运行状态</h2>
            <div className="workbench-tabs">
              <button className={queuePage === 'queue' ? 'active' : ''} onClick={() => setQueuePage('queue')}>
                队列
              </button>
              <button className={queuePage === 'log' ? 'active' : ''} onClick={() => setQueuePage('log')}>
                日志
              </button>
            </div>
            <span className="workbench-spacer" />
            {queuePage === 'log' && (
              <>
                <Button
                  size="small"
                  appearance="subtle"
                  title="刷新日志"
                  icon={<ArrowClockwiseRegular />}
                  onClick={() => void voiceController.syncStatus()}
                />
                <Button
                  size="small"
                  appearance="subtle"
                  title="导出日志"
                  icon={<ArrowDownloadRegular />}
                  disabled={logs.length === 0}
                  onClick={() => void exportLogs()}
                />
              </>
            )}
            {queuePage === 'queue' && (
              <>
                <Button
                  size="small"
                  appearance="subtle"
                  title="清理未被任何场景引用的缓存音频"
                  icon={<WrenchRegular />}
                  onClick={() => setChangeDialogOpen(true)}
                />
                <Button
                  size="small"
                  appearance="subtle"
                  title="清空已完成的任务"
                  icon={<DismissRegular />}
                  onClick={() => {
                    voiceController.clearFinishedTasks();
                    setQueuePage('queue');
                  }}
                />
              </>
            )}
          </div>

          <p className="workbench-summary">
            待处理 {summary.pending}（测试 {summary.pendingTest} · 生成 {summary.pendingGenerate}）
            {summary.running > 0 && ` · 运行中 ${summary.running}`}
            {summary.pending + summary.running > 0 && ` · 预计 ${formatEta(summary.etaMillis)}`}
          </p>

          {queuePage === 'queue' ? (
            <div className="workbench-scroll">
              {voiceController.allTasks().length === 0 && (
                <p className="voice-dialog-empty">队列为空。在场景卡的配音模式中点击「测试」或「生成」。</p>
              )}
              {voiceController.allTasks().map((task) => (
                <div key={task.id} className={`voice-task ${task.status}`}>
                  <span className={`history-kind ${task.kind}`}>
                    {task.kind === 'test' ? '测试' : '生成'} x{task.params.sampleSteps}
                  </span>
                  <span className="voice-task-text">{task.text || '（空）'}</span>
                  <span className="voice-task-character">{task.characterName}</span>
                  <span className="voice-task-status">
                    {task.status === 'pending' && '等待中'}
                    {task.status === 'running' && (
                      <>
                        <Spinner size="extra-tiny" /> 生成中
                      </>
                    )}
                    {task.status === 'done' && '已完成'}
                    {task.status === 'failed' && '失败'}
                    {task.status === 'canceled' && '已取消'}
                  </span>
                  {task.status === 'running' && <ProgressBar />}
                  {task.status === 'failed' && task.error && (
                    /*
                      报错只占一行 (整行独占, 见 `.voice-task-error`): 原文有几十行,
                      直接铺开会把整个任务项撑成一屏。点开弹窗看全文。
                    */
                    <button
                      type="button"
                      className="error-chip voice-task-error"
                      title="查看完整报错"
                      onClick={() => setErrorTask(task)}
                    >
                      <ErrorCircleRegular className="error-chip-icon" />
                      <span className="error-chip-text">{errorSummary(task.error)}</span>
                      <span className="error-chip-more">详情</span>
                    </button>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <div className="workbench-scroll workbench-log">
              {logs.length === 0 && <p className="voice-dialog-empty">暂无日志。</p>}
              {logs.map((line, index) => (
                <div key={index} className="voice-log-line">
                  {line}
                </div>
              ))}
            </div>
          )}
        </section>
      </div>

      {errorTask && (
        <VoiceErrorDialog
          error={errorTask.error ?? null}
          description={`${errorTask.characterName} · ${errorTask.kind === 'test' ? '测试' : '生成'} x${
            errorTask.params.sampleSteps
          } · ${new Date(errorTask.createdAt).toLocaleString()}`}
          onClose={() => setErrorTask(null)}
        />
      )}

      {/* -------- 角色库: 占满剩余高度 -------- */}
      <RoleListPanel />

      <VoiceCacheDialog open={changeDialogOpen} onClose={() => setChangeDialogOpen(false)} />
    </div>
  );

  /** 导出运行日志为文本文件 */
  async function exportLogs() {
    const destination = await saveDialog({
      defaultPath: 'gsov-日志.txt',
      filters: [{ name: '文本文件', extensions: ['txt', 'log'] }],
    });
    if (typeof destination !== 'string') return;
    await fs.writeText(destination, logs.join('\n'));
  }
}

/** 切换启动方式时的默认字段值 */
function defaultMode(kind: string, launch: LaunchConfig): LaunchMode {
  switch (kind) {
    case 'conda':
      return { kind: 'conda', env: '', program: null };
    case 'python':
      return { kind: 'python', program: 'python' };
    case 'command':
      return { kind: 'command', command: defaultCommand(launch) };
    default:
      return { kind: 'embedded', program: `${launch.root}\\runtime\\python.exe` };
  }
}

/**
 * 自定义命令的默认值: 直接给出"用整合包内置运行时跑它的控制脚本"这条等价命令。
 *
 * 这样切到自定义命令时拿到的是一个**已经能跑**的命令行 (路径已指向整合包),
 * 按需改一处即可; 而不是 `C:\gsov\start.bat` 那种要自己从零猜的示例。
 */
function defaultCommand(launch: LaunchConfig): string {
  const root = launch.root.replace(/[\\/]+$/, '');
  return `"${root}\\runtime\\python.exe" "${root}\\${launch.script}" -a ${launch.host} -p ${launch.port} -c ${launch.inferConfig}`;
}

function modeLabel(launch: LaunchConfig): string {
  switch (launch.mode.kind) {
    case 'embedded':
      return '使用整合包自带的 runtime\\python.exe（自动加 -I 隔离）';
    case 'conda':
      return '通过 conda run 调用指定环境（等于先激活环境再执行，不加 -I）';
    case 'python':
      return '使用指定的 Python 解释器（不隔离）';
    default:
      return '整条命令原样执行，Ink 只负责启动与收尾';
  }
}
